@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    if (!super.equals(o)) {
        return false;
    }
    AnythingBut that = (AnythingBut) o;
    return isNumeric == that.isNumeric && (Objects.equals(values, that.values));
}
